export function levelProfile(id,level,era=0){if(!BUILDINGS[id]&&!UNITS[id])throw Error('Diseño desconocido');if(!Number.isInteger(level)||level<1||level>10||!Number.isInteger(era)||era<0||era>=ERAS.length)throw Error('Era o nivel inválido');const b=BUILDINGS[id],levels=b?LEVELS:UNIT_LEVELS,style=ARCHITECTURES.find(a=>era>=a.from&&era<=a.to);return{id,level,era,style:style.name,material:style.material,name:levels[level-1].name,change:levels[level-1].change,detail:levels[level-1].detail||'Grado de equipo propuesto, sin experiencia automática.',role:b?.outputs||UNITS[id].role,modules:levels.slice(0,level).map(l=>l.name),status:b?.status||UNITS[id].status};}
